alter table public.cineo_experience add column shortcut_groups jsonb not null default '{}';
create function public.cineo_sync_playback(actor uuid,viewer uuid,eid bigint,pos integer,duration integer,done boolean,observed timestamptz) returns jsonb language plpgsql security invoker set search_path='' as $$declare k text:=coalesce(viewer::text,'account');stored_observed timestamptz;begin
 if duration not between 1 and 14400000 or pos not between 0 and duration or observed>now()+interval '1 minute' or observed<now()-interval '90 days' then raise exception 'Progresso ou horário inválido';end if;
 if viewer is not null and not exists(select 1 from public.cineo_viewers where id=viewer and user_id=actor) then raise exception 'Perfil indisponível';end if;
 insert into public.cineo_playback_clock(user_id,viewer_key,episode_id,observed_at) values(actor,k,eid,observed) on conflict do nothing;
 select observed_at into stored_observed from public.cineo_playback_clock where user_id=actor and viewer_key=k and episode_id=eid for update;
 if stored_observed>observed then return jsonb_build_object('ok',true,'applied',false,'reason','Há um progresso mais recente em outro aparelho.');end if;
 update public.cineo_playback_clock set observed_at=observed where user_id=actor and viewer_key=k and episode_id=eid;
 if viewer is null then insert into public.cineo_progress(user_id,episode_id,position_ms,duration_ms,completed,updated_at) values(actor,eid,pos,duration,done,now()) on conflict(user_id,episode_id) do update set position_ms=excluded.position_ms,duration_ms=excluded.duration_ms,completed=excluded.completed,updated_at=excluded.updated_at;
 else insert into public.cineo_viewer_progress(viewer_id,episode_id,position_ms,duration_ms,completed,updated_at) values(viewer,eid,pos,duration,done,now()) on conflict(viewer_id,episode_id) do update set position_ms=excluded.position_ms,duration_ms=excluded.duration_ms,completed=excluded.completed,updated_at=excluded.updated_at;end if;
 return jsonb_build_object('ok',true,'applied',true);end$$;
create function public.cineo_reorder_chapters(actor uuid,sid bigint,season_number integer,ids bigint[]) returns void language plpgsql security invoker set search_path='' as $$declare s public.cineo_shows;n integer:=1;eid bigint;expected integer;temporary_season integer;begin select * into s from public.cineo_shows where id=sid for update;if s.owner_id is distinct from actor or s.status not in ('draft','rejected') then raise exception 'Reordene capítulos somente em uma produção em rascunho';end if;select count(*) into expected from public.cineo_episodes where show_id=sid and season=season_number;if expected<>cardinality(ids) or expected<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not exists(select 1 from public.cineo_episodes where id=x and show_id=sid and season=season_number)) then raise exception 'Lista de capítulos inválida';end if;
 -- Move through an unused, valid season to preserve immediate uniqueness and chapter bounds.
 select gs.value into temporary_season from generate_series(1,1000) as gs(value) where not exists(select 1 from public.cineo_episodes where show_id=sid and season=gs.value) limit 1;if temporary_season is null then raise exception 'Nenhuma temporada temporária disponível';end if;
 update public.cineo_episodes set season=temporary_season where show_id=sid and season=season_number;
 foreach eid in array ids loop update public.cineo_episodes set season=season_number,episode_number=n where id=eid;n:=n+1;end loop;
end$$;
create function public.cineo_decide_case(actor uuid,cid uuid,decision text,note text) returns void language plpgsql security invoker set search_path='' as $$declare c public.cineo_cases;r text;s public.cineo_shows;e public.cineo_episodes;p public.cineo_proposals;patch jsonb;begin
 select * into c from public.cineo_cases where id=cid for update;if c.id is null or c.status<>'open' then raise exception 'Caso indisponível';end if;
 if exists(select 1 from public.cineo_admins where user_id=actor) then r:='admin';else select role into r from public.cineo_staff where user_id=actor;if c.assignee is distinct from actor then raise exception 'Caso atribuído a outra pessoa';end if;end if;
 if r is null or (c.kind='ticket' and r not in ('admin','support')) or(c.kind<>'ticket' and r not in ('admin','reviewer')) then raise exception 'Acesso restrito';end if;
 if decision not in ('approved','rejected','resolved','dismissed','restore') or length(note)>2000 or(decision='rejected' and length(trim(note))<3) then raise exception 'Decisão ou motivo inválidos';end if;
 if c.kind='show' then select * into s from public.cineo_shows where id=c.target_id::bigint for update;if s.status<>'pending' or decision not in ('approved','rejected') then raise exception 'Produção não está em análise';end if;if decision='approved' and exists(select 1 from public.cineo_media_jobs j join public.cineo_episodes ep on ep.id=j.episode_id where ep.show_id=s.id and j.status<>'ready') then raise exception 'Vídeos ainda não validados';end if;update public.cineo_shows set status=decision,reason=case when decision='rejected' then note else '' end where id=s.id;if decision='approved' then perform public.cineo_notify(s.id,null);end if;
 elsif c.kind='episode' then select * into e from public.cineo_episodes where id=c.target_id::bigint for update;select * into s from public.cineo_shows where id=e.show_id for update;if e.review_status<>'pending' or s.status<>'approved' or decision not in ('approved','rejected') then raise exception 'Capítulo não está em análise';end if;if decision='approved' and exists(select 1 from public.cineo_media_jobs where episode_id=e.id and status<>'ready') then raise exception 'Arquivo ainda não validado';end if;update public.cineo_episodes set review_status=decision,review_reason=case when decision='rejected' then note else '' end where id=e.id;if decision='approved' then perform public.cineo_notify(s.id,e.id);end if;
 elsif c.kind='proposal' then select * into p from public.cineo_proposals where id=c.target_id::uuid for update;select * into s from public.cineo_shows where id=p.show_id for update;if p.status<>'pending' or s.status<>'approved' or decision not in ('approved','rejected') then raise exception 'Alteração indisponível';end if;patch=p.content->'patch';if decision='approved' then if (p.content->'base'->>'title') is distinct from s.title or(p.content->'base'->>'cover_path') is distinct from s.cover_path then raise exception 'A publicação mudou. Solicite uma proposta atualizada';end if;update public.cineo_shows set title=coalesce(patch->>'title',title),synopsis=coalesce(patch->>'synopsis',synopsis),genre=coalesce(patch->>'genre',genre),rating=coalesce(patch->>'rating',rating),cover_path=coalesce(patch->>'cover_path',cover_path),banner_path=coalesce(patch->>'banner_path',banner_path) where id=s.id;end if;update public.cineo_proposals set status=decision,reason=note where id=p.id;
 elsif c.kind='ticket' then if length(trim(note))<3 then raise exception 'Escreva a resposta';end if;update public.cineo_tickets set reply=note,status='closed' where id=c.target_id::bigint;
 elsif c.kind='appeal' then if length(trim(note))<3 then raise exception 'Explique a reavaliação';end if;update public.cineo_appeals set reply=note,status='answered' where id=c.target_id::bigint;
 elsif c.kind='report' then update public.cineo_reports set status=case when decision='dismissed' then 'dismissed' else 'resolved' end where id=c.target_id::bigint;
 else raise exception 'Tipo de caso inválido';end if;
 insert into public.cineo_case_actions(case_id,user_id,action,details) values(c.id,actor,decision,jsonb_build_object('note',note));update public.cineo_cases set status='resolved' where id=c.id;
end$$;
revoke all on function public.cineo_sync_playback(uuid,uuid,bigint,integer,integer,boolean,timestamptz),public.cineo_reorder_chapters(uuid,bigint,integer,bigint[]),public.cineo_decide_case(uuid,uuid,text,text) from public,anon,authenticated;
grant execute on function public.cineo_sync_playback(uuid,uuid,bigint,integer,integer,boolean,timestamptz),public.cineo_reorder_chapters(uuid,bigint,integer,bigint[]),public.cineo_decide_case(uuid,uuid,text,text) to service_role;
